class Solution {
    public: vector<string> findWords(vector<string>& words){
        vector<int> row(26);
        for(char c:string("qwertyuiop"))row[c-'a']=1;
        for(char c:string("asdfghjkl"))row[c-'a']=2;
        for(char c:string("zxcvbnm"))row[c-'a']=3;
        vector<string> answer;
        for(string word:words){
            int target=row[tolower(word[0])-'a'];
            bool valid=true;
            for(char c:word)if(row[tolower(c)-'a']!=target){
                valid=false;
                break;
            }
            if(valid)answer.push_back(word);
        }
        return answer;
    }
